#include <bits/stdc++.h>
using namespace std;

int main() {
	int n;
	cin >> n;

	auto f = [&](int x) -> int {
		int res = 0;
		while (x) {
			res += x % 10;
			x /= 10;
		}
		return res;
	};

	vector<int> a(n + 1);
	a[0] = 1;
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j < i; j++) a[i] += f(a[j]);
	}
	cout << a[n] << '\n';
}
